begin;
insert into auth.users(id,email,raw_user_meta_data,raw_app_meta_data,aud,role,encrypted_password,email_confirmed_at,created_at,updated_at)select('fca10000-0000-4000-8000-'||lpad(x::text,12,'0'))::uuid,'synthetic-cohost-'||x||'@fixture.invalid',jsonb_build_object('full_name','Cohost fixture','account_type_request','EXTERNAL'),'{}','authenticated','authenticated','fixture-no-password',now(),now(),now()from generate_series(1,3)x;
insert into auth.sessions(id,user_id)select('fca20000-0000-4000-8000-'||lpad(x::text,12,'0'))::uuid,('fca10000-0000-4000-8000-'||lpad(x::text,12,'0'))::uuid from generate_series(1,3)x;
insert into cbgpu_schools.schools(id,official_name,normalized_name,display_name,type,region,configuration,features,status)values('fixture-cohost-b','Cohost B','cohost b','Cohost B','HIGH_SCHOOL','Synthetic','{}',array['contests'],'APPROVED'),('fixture-cohost-c','Cohost C','cohost c','Cohost C','HIGH_SCHOOL','Synthetic','{}',array['contests'],'APPROVED');
insert into cbgpu_schools.memberships(user_id,school_id,membership_type,status,verified,school_roles)values('fca10000-0000-4000-8000-000000000001','cbsh','STUDENT','ACTIVE',true,'{}'),('fca10000-0000-4000-8000-000000000002','fixture-cohost-b','TEACHER','ACTIVE',true,array['SCHOOL_ADMIN']),('fca10000-0000-4000-8000-000000000003','fixture-cohost-c','TEACHER','ACTIVE',true,array['SCHOOL_OWNER']);
insert into public.contests(id,host_id,title,fields,school_id,access_scope)values('fca30000-0000-4000-8000-000000000001','fca10000-0000-4000-8000-000000000001','Synthetic jointly organized contest','[{"id":"fca40000-0000-4000-8000-000000000001","type":"text","label":"Fixture answer","description":"","required":false}]','cbsh','PUBLIC');
select set_config('request.jwt.claims','{"sub":"fca10000-0000-4000-8000-000000000001","role":"authenticated","session_id":"fca20000-0000-4000-8000-000000000001"}',true);set local role authenticated;
create temp table cohost_invite as select public.cbgpu_contest_organizer_schools('invite','{"contest_id":"fca30000-0000-4000-8000-000000000001","school_id":"fixture-cohost-b","revision":0}')value;
do $$begin begin perform public.cbgpu_contest_organizer_schools('accept',jsonb_build_object('id',(select value#>>'{invitation,id}'from cohost_invite),'revision',1));raise exception 'OWNER_CANNOT_ACCEPT_FOR_TARGET';exception when insufficient_privilege then null;end;begin perform count(*)from cbgpu_schools.contest_organizer_schools;raise exception 'RAW_INVITES_LEAK';exception when insufficient_privilege then null;end;end$$;
reset role;
do $$begin if cbgpu_schools.accepted_organizer_school_names('fca30000-0000-4000-8000-000000000001')is not null then raise exception 'PENDING_PUBLIC_LEAK';end if;end$$;
select set_config('request.jwt.claims','{"sub":"fca10000-0000-4000-8000-000000000003","role":"authenticated","session_id":"fca20000-0000-4000-8000-000000000003"}',true);set local role authenticated;
do $$begin begin perform public.cbgpu_contest_organizer_schools('inbox','{"school_id":"fixture-cohost-b"}');raise exception 'CROSS_SCHOOL_INBOX';exception when insufficient_privilege then null;end;begin perform public.cbgpu_contest_organizer_schools('invite','{"contest_id":"fca30000-0000-4000-8000-000000000001","school_id":"fixture-cohost-c"}');raise exception 'NON_OWNER_INVITE';exception when insufficient_privilege then null;end;end$$;
select set_config('request.jwt.claims','{"sub":"fca10000-0000-4000-8000-000000000002","role":"authenticated","session_id":"fca20000-0000-4000-8000-000000000002"}',true);
do $$declare result jsonb;begin result:=public.cbgpu_contest_organizer_schools('inbox','{"school_id":"fixture-cohost-b"}');if jsonb_array_length(result->'items')<>1 or result::text like '%invited_by%'then raise exception 'INBOX_SCOPE_OR_ACTOR_LEAK';end if;end$$;
select public.cbgpu_contest_organizer_schools('accept',jsonb_build_object('id',(select value#>>'{invitation,id}'from cohost_invite),'revision',1));
reset role;
do $$declare result jsonb;begin if cbgpu_schools.accepted_organizer_school_names('fca30000-0000-4000-8000-000000000001')<>'Cohost B'then raise exception 'ACCEPTED_PUBLIC_NAME';end if;if exists(select 1 from public.event_hosts where contest_id='fca30000-0000-4000-8000-000000000001')or(select allowed_school_ids from public.contests where id='fca30000-0000-4000-8000-000000000001')<>'{}'then raise exception 'ACCEPTANCE_GRANTED_OPERATOR_OR_PARTICIPATION';end if;result:=public.cbgpu_public_content('contest','{"id":"fca30000-0000-4000-8000-000000000001"}');if result#>>'{item,organizer_school_names}'<>'Cohost B'or result::text like '%fca10000%'then raise exception 'CURATED_PUBLIC_NAMES_OR_ACTOR_LEAK';end if;end$$;
select set_config('request.jwt.claims','{"sub":"fca10000-0000-4000-8000-000000000001","role":"authenticated","session_id":"fca20000-0000-4000-8000-000000000001"}',true);set local role authenticated;
do $$begin begin perform public.cbgpu_contest_organizer_schools('revoke',jsonb_build_object('id',(select value#>>'{invitation,id}'from cohost_invite),'revision',1));raise exception 'STALE_REVISION_OVERWRITE';exception when serialization_failure then null;end;end$$;
select public.cbgpu_contest_organizer_schools('revoke',jsonb_build_object('id',(select value#>>'{invitation,id}'from cohost_invite),'revision',2));
reset role;
do $$begin if cbgpu_schools.accepted_organizer_school_names('fca30000-0000-4000-8000-000000000001')is not null or(select count(*)from cbgpu_schools.contest_organizer_audit where invitation_id=(select(value#>>'{invitation,id}')::uuid from cohost_invite))<>3 then raise exception 'REVOKE_PUBLIC_OR_AUDIT';end if;end$$;
select set_config('request.jwt.claims','{"sub":"fca10000-0000-4000-8000-000000000001","role":"authenticated","session_id":"fca20000-0000-4000-8000-000000000001"}',true);set local role authenticated;
select public.cbgpu_contest_organizer_schools('invite','{"contest_id":"fca30000-0000-4000-8000-000000000001","school_id":"fixture-cohost-b","revision":3}');
reset role;delete from auth.sessions where id='fca20000-0000-4000-8000-000000000002';
select set_config('request.jwt.claims','{"sub":"fca10000-0000-4000-8000-000000000002","role":"authenticated","session_id":"fca20000-0000-4000-8000-000000000002"}',true);set local role authenticated;
do $$begin begin perform public.cbgpu_contest_organizer_schools('accept',jsonb_build_object('id',(select value#>>'{invitation,id}'from cohost_invite),'revision',4));raise exception 'REVOKED_SESSION_ACCEPT';exception when insufficient_privilege then null;end;end$$;
rollback;
select 'CONTEST_ORGANIZER_SCHOOL_TESTS_PASSED';
